  function isUrgentHealthQuestion(raw){const q=String(raw||'').toLowerCase();return /(?:chest (?:pain|pressure|tightness)|trouble breathing|difficulty breathing|can(?:not|'t) breathe|choking|face droop|one[- ]sided weakness|slurred speech|stroke symptoms?|sudden severe headache|severe allergic reaction|anaphyl|swollen tongue|swollen throat|unconscious|seizure|heavy bleeding|vomit(?:ing)? blood|cough(?:ing)? blood|overdose|poison(?:ed|ing)|suicid|kill myself|self[- ]?harm)/.test(q)}
