  function selectFemaleFallbackVoice(){if(!('speechSynthesis'in window))return null;const voices=window.speechSynthesis.getVoices();const ranked=[/google uk english female/i,/microsoft (sonia|libby|aria|jenny|zira|ava|emma)/i,/samantha/i,/serena/i,/victoria/i,/karen/i,/moira/i,/tessa/i,/female/i];for(const re of ranked){const v=voices.find(v=>/^en(?:-|_)/i.test(v.lang||'')&&re.test(v.name||''));if(v)return v}return voices.find(v=>/^en-ZA$/i.test(v.lang||''))||voices.find(v=>/^en-GB$/i.test(v.lang||''))||voices.find(v=>/^en(?:-|_)/i.test(v.lang||''))||null}
